"""Builds the LPS document: SERS spectrum compared with the lipid A simulation (and bulk LPS)."""
import os,pickle
import fr_docs as FD
S=r"C:\Users\sukes\AppData\Local\Temp\claude\C--Users-sukes-Downloads-sukesh\f9c0734c-e0bb-4f52-a4e5-d9f33e9bce00\scratchpad\sersfinal"
Rz=pickle.load(open(S+r'\lps_res.pkl','rb')); res=Rz['res']; f1,f2,f3,f4=Rz['figs']
OUT=os.path.join(FD.OUT,'08_LPS_SERS_vs_Simulation'); os.makedirs(OUT,exist_ok=True)
n_ag=sum(r['status']=='agrees' for r in res); n_sh=sum(r['status']=='shifted' for r in res); n_no=sum(r['status']=='none' for r in res)
typed=[r for r in res if r['typed']]
d=FD.Doc('LPS: SERS Spectrum Compared with the Molecular Simulation','Surface-enhanced Raman bands of lipopolysaccharide on etched silicon and the calculated spectrum of the lipid A model')
d.h1('Executive summary')
d.p(f"A reproducible set of ten bands was found in the SERS spectra of LPS on etched silicon (on {Rz['n']} of 35 LPS spots). These bands were compared with the calculated Raman spectrum of the whole-molecule lipid A model, and with the bulk LPS reference spectrum. Each of the ten SERS bands has a calculated vibration within {max(abs(r['delta']) for r in res if r['delta'] is not None):.0f} cm⁻¹: {n_ag} agree within 10 cm⁻¹ and {n_sh} is shifted by 11 cm⁻¹. The two bands with a published assignment, 1330 cm⁻¹ (C–H deformation) and 1455 cm⁻¹ (CH₂/CH₃ deformation), fall within 1.1 cm⁻¹ of calculated C–H bending vibrations of the expected type.")
d.p(f"The agreement cannot be counted as evidence that the bands belong to LPS. The model has {Rz['nmodes']} vibrations between 400 and 1800 cm⁻¹, so a calculated vibration lies near almost any position: when the calculated positions are displaced by a random 15 to 70 cm⁻¹, {Rz['dec_mean']:.1f} of the ten bands still fall within 10 cm⁻¹ of a calculated vibration, against {Rz['real']} for the real positions (p = {Rz['p']:.2f}). The overall shape also does not match (correlation {Rz['r_calc']:.2f} with the calculation and {Rz['r_bulk']:.2f} with the bulk LPS spectrum). The bulk LPS peaks, including the strongest at 425 cm⁻¹, are absent from the SERS spectra. The SERS pattern is consistent with CH₂ and CH₃ groups of an organic layer on the silicon, with LPS as one possible source; it is not an identification.")
d.h1('Objective')
d.p("To test whether the bands seen in the SERS spectra of LPS correspond to vibrations predicted for the molecular structure of lipid A, the conserved core of LPS, and to explain bands that are shifted. SERS (surface-enhanced Raman spectroscopy) is Raman spectroscopy in which molecules on a roughened metal-coated surface give a strongly amplified signal; it often enhances different bands than ordinary Raman spectroscopy of the bulk powder, so the SERS and bulk spectra of one molecule do not have to look alike.")
d.h1('Data and approach')
d.b("Ten bands that repeat on 21 of 35 LPS spots (mean spectrum of those spots; positions are the means of the spots). Spectra were processed with background subtraction, spike removal, smoothing and baseline removal, and scaled to the silicon peak at 518 cm⁻¹.","SERS data:")
d.b("A whole-molecule model of lipid A with two Kdo sugars (201 atoms, charge −4, with shortened fatty-acid chains), calculated for the isolated molecule with density functional theory (B3LYP, small 3-21G basis set). A calculated spectrum is a prediction of the Raman signals expected from the structure. Frequencies were multiplied by 0.965 and each vibration was drawn as a peak 12 cm⁻¹ wide. The type of each vibration (for example C–H bending, C–O and C–C stretching, skeletal deformation) was assigned from which atoms move; these labels are tentative.","Simulation:")
d.b("No spectrum was shifted or rescaled to improve the match; each is scaled to its own maximum, and the silicon region is left out. Each SERS band is matched to the nearest calculated vibration within 50 cm⁻¹ that has appreciable intensity. For bands with a published assignment (1009, 1330 and 1455 cm⁻¹) the calculated vibration must also be of the matching type. For the other seven bands no vibration type is assigned in the literature (two of them, 785 and 1592 cm⁻¹, lie at or near peaks listed as common to commercial endotoxins without an assignment), so the match is by position only. 'Agrees' means a difference of 10 cm⁻¹ or less; 'shifted' means 10 to 50 cm⁻¹.","Comparison:")
d.h1('Results')
d.h2('The SERS spectrum of LPS')
d.figure(f1,"Mean SERS spectrum of the LPS spots that carry the band set (red line, with ± 1 standard deviation as the shaded band), scaled to the height of the silicon peak. Each number marks a band at its position on the curve.")
d.p("The strongest band is at 1455 cm⁻¹; the others are weaker and several are broad or overlapping (1330 and 1368 cm⁻¹ sit on one broad feature).")
d.h2('SERS, simulation and bulk spectrum together')
d.figure(f2,"Bulk LPS reference (top), SERS mean spectrum (middle) and calculated spectrum of the lipid A model (bottom). In each panel the dots and numbers mark only the peaks of that curve, at the position where they occur on it: the bulk peaks (top), the SERS bands (middle) and the calculated vibrations that correspond to the SERS bands (bottom). Because each curve is marked separately, a mark and the neighbouring curve may not line up: the same vibration appears at slightly different positions in the three spectra (see the table). Numbers on the curves are read from the plotted curve (the apex of the mean spectrum) and can differ by a few cm⁻¹ from the band positions in the table, which are averages over individual spots. Grey bands: silicon peak (middle) and glass zone (top, bottom), which are not compared.")
d.p("None of the bulk LPS peaks (425, 766, 861, 996 and 1080 cm⁻¹) appears in the SERS spectrum, although the calculation has vibrations near all of them. Conversely, the strongest SERS bands (1455, 619, 878) correspond to calculated vibrations of moderate intensity, and the strongest calculated peak, near 1516 cm⁻¹, has no strong SERS counterpart (the nearest SERS band is 1536 cm⁻¹).")
d.h2('Band-by-band comparison')
ST={'agrees':'Agrees','shifted':'Shifted','none':'Not reproduced'}
LITO={785:'794, listed as a common LPS peak without assignment (9 cm⁻¹ away)',1592:'1592, listed as a common LPS peak without assignment'}
rows=[]
for r in res:
    typ='' if r['typed'] else ' (type not assigned)'
    rows.append([f"{r['exp']:.0f}",(f"{r['calc']:.0f}" if r['calc'] else '—'),(f"{r['delta']:+.0f}" if r['delta'] is not None else '—'),(r['label'] if r['label'] else '—'),r['desc'] if r['typed'] else LITO.get(r['key'],'none in the literature checked'),ST[r['status']]+typ])
d.table(['SERS band (cm⁻¹)','Calculated (cm⁻¹)','Difference','Calculated vibration','Published assignment','Result'],rows,[1.9,2.0,1.7,4.2,4.4,2.6],'SERS bands of LPS and the corresponding calculated vibrations. Difference = SERS minus calculated.')
d.figure(f3,"Close-ups of the SERS bands. Upper curve: SERS mean; lower curve: calculation; each is scaled to its tallest peak in the window. Dashed lines mark the SERS band (above) and the corresponding calculated vibration (below); the arrow gives the shift where it exceeds 10 cm⁻¹.")
d.p("In several windows the calculated spectrum shows only a shoulder or no distinct peak at the matched position (for example at 1329 and 1457 cm⁻¹). The match rests on the position of an individual calculated vibration, not on a visible calculated peak, which is another reason to treat the agreement with caution.")
d.h2('The shifted band')
r=[x for x in res if x['status']=='shifted'][0]
d.p(f"The SERS band at {r['exp']:.0f} cm⁻¹ is matched to a calculated vibration at {r['calc']:.0f} cm⁻¹ (difference {r['delta']:+.0f} cm⁻¹), which the analysis labels as N–H bending (amide and ammonium-type motion). No vibration type is assigned to this band in the literature, so the correspondence is by position only. A calculated frequency 11 cm⁻¹ lower than the measured one is the size of offset expected from the small basis set and the isolated, gas-phase charged model; on a surface the molecule binds, hydrogen bonds and is oriented, which shifts and re-weights bands. The assignment is therefore tentative.")
d.h2('Where the matched vibrations are in the molecule')
d.figure(f4,"Atoms that move most in the calculated vibrations that correspond to the SERS bands. Each colour is one vibration (key at right); hydrogen atoms are assigned to the atom they are bonded to. The vibrations are spread over several groups rather than one bond.")
d.h1('Interpretation')
d.b("Positions: all ten SERS bands lie within 11 cm⁻¹ of a calculated vibration of the lipid A model, and the two bands with a published assignment, 1330 and 1455 cm⁻¹, match calculated C–H bending vibrations within about 1 cm⁻¹. This is consistent with CH₂/CH₃ and C–H groups, which are present in LPS (acyl chains and sugars) and in many other organic layers.")
d.b(f"Chance: because the model has many vibrations, the same level of agreement is reached for randomly displaced positions about nine times in ten (p = {Rz['p']:.2f}). The position agreement is therefore not evidence that the bands belong to LPS.")
d.b("Pattern: the SERS spectrum does not reproduce the bulk LPS peaks or the calculated intensity pattern. This can happen because SERS enhances only the groups close to or lying on the metal surface, but it also removes the support a match would have given.")
d.b("Sample controls: there was no blank or solvent-only control recorded in the same period as the LPS spots, so contamination from preparation or handling cannot be excluded.")
d.h1('Conclusion and next step')
d.p("The SERS bands of the LPS spots are consistent with the vibration types predicted by the lipid A model, but this agreement is not stronger than chance and the overall spectra do not match, so the bands are not yet attributed to LPS. The most useful next steps are to repeat the LPS measurement on a fresh substrate with a solvent-only control prepared in the same way and a blank at the start and end of the set, and to measure bulk LPS on the same type of silicon to see directly which bands LPS gives there. On the calculation side, a larger basis set with water and counter-ions, and a model that includes the sugar-bound surface orientation, would test whether the bands near 619, 878 and 1238 cm⁻¹ can be assigned.")
path=os.path.join(OUT,'LPS_SERS_vs_Simulation_Comparison.docx'); d.save(path); print(path)
